"""Pandera schemas for generated data-pipeline artifacts."""
from __future__ import annotations

import pandera.pandas as pa

WAVES = ["IFLS4", "IFLS5"]
BINARY = [0, 1]


def _wave_column() -> pa.Column:
    return pa.Column(str, checks=pa.Check.isin(WAVES), nullable=False, coerce=True)


def _id_column() -> pa.Column:
    return pa.Column(str, nullable=False, coerce=True)


def _binary_column(*, nullable: bool = False) -> pa.Column:
    return pa.Column(
        int,
        checks=pa.Check.isin(BINARY),
        nullable=nullable,
        coerce=True,
    )


# Generated by code/data/01_extract_individuals.py -> data/generated/individuals.parquet
INDIVIDUALS_SCHEMA = pa.DataFrameSchema(
    {
        # Stable IFLS person identifier, used as the person-level merge key.
        "pidlink": _id_column(),
        # Wave-specific household identifier used for household-level merges.
        "hhid": _id_column(),
        # Individual interview date built from the wave-specific cover/date fields.
        "interview_date": pa.Column(pa.DateTime, nullable=False, coerce=True),
        # BPS two-digit province code from the household screening file.
        "province_code": pa.Column(int, nullable=False, coerce=True),
        # BPS four-digit kabupaten code, computed as province*100 plus within-province kabupaten.
        "kabupaten_code": pa.Column(int, nullable=False, coerce=True),
        # BPS seven-digit kecamatan code, computed from kabupaten_code and within-kabupaten kecamatan.
        "kecamatan_code": pa.Column(int, nullable=False, coerce=True),
        # IFLS survey wave for the person record.
        "wave": _wave_column(),
    },
    strict=True,
    ordered=True,
)


# Generated by code/data/04_score_cesd.py -> data/generated/cesd_scores.parquet
CESD_SCORES_SCHEMA = pa.DataFrameSchema(
    {
        # Stable IFLS person identifier, used as the person-level merge key.
        "pidlink": _id_column(),
        # Number of CES-D items contributing to the person-wave score.
        "n_items": pa.Column(int, checks=pa.Check.between(0, 10), nullable=False, coerce=True),
        # Sum of CES-D-10 frequency scores after reverse-coding positive items.
        "cesd_raw": pa.Column(float, checks=pa.Check.between(0, 30), nullable=False, coerce=True),
        # IFLS survey wave that produced the mental-health record.
        "wave": _wave_column(),
        # IFLS4 screener count of endorsed CES-D items; missing for IFLS5.
        "cesd10_count": pa.Column(float, checks=pa.Check.between(0, 10), nullable=True, coerce=True),
        # Indicator for CES-D raw score at or above the cutoff of 10.
        "depressed": _binary_column(),
    },
    strict=True,
    ordered=True,
)

# Generated by code/data/05_build_stressors.py -> data/generated/stressors.parquet
STRESSORS_SCHEMA = pa.DataFrameSchema(
    {
        # Stable IFLS person identifier, used as the person-level merge key.
        "pidlink": _id_column(),
        # Wave-specific household identifier used for household-level merges.
        "hhid": _id_column(),
        # Respondent age from the household roster after sentinel cleaning.
        "age": pa.Column(float, checks=pa.Check.between(0, 120), nullable=True, coerce=True),
        # Respondent sex from the roster, normalized to F/M.
        "sex": pa.Column(str, checks=pa.Check.isin(["F", "M"]), nullable=False, coerce=True),
        # Indicator for currently married marital status.
        "married": _binary_column(),
        # Indicator for widowed marital status.
        "widowed": _binary_column(),
        # Approximate years of schooling mapped from IFLS education level.
        "edu_yrs": pa.Column(int, checks=pa.Check.ge(0), nullable=False, coerce=True),
        # IFLS survey wave for the stressor/covariate record.
        "wave": _wave_column(),
        # Household size used in per-capita expenditure calculations.
        "hhsize": pa.Column(float, checks=pa.Check.ge(0), nullable=True, coerce=True),
        # Nominal monthly per-capita household expenditure.
        "pce": pa.Column(float, checks=pa.Check.ge(0), nullable=True, coerce=True),
        # Natural log of monthly per-capita expenditure.
        "pce_log": pa.Column(float, nullable=True, coerce=True),
        # Within-wave quintile of monthly per-capita expenditure.
        "pce_quintile": pa.Column(float, checks=pa.Check.between(1, 5), nullable=True, coerce=True),
        # Household reported any natural disaster in the past 5 years.
        "disaster_5yr": _binary_column(),
        # Household reported a severe natural disaster in the past 5 years.
        "disaster_severe_5yr": _binary_column(),
        # Household had a loan application rejected.
        "loan_rejected": _binary_column(),
        # Respondent's primary job is in agriculture, forestry, or fishery.
        "agri_occupation": _binary_column(),
    },
    strict=True,
    ordered=True,
)

# Generated by code/data/03_fetch_temperature_gee.py -> data/generated/daily_temperature_kab.parquet
DAILY_TEMPERATURE_SCHEMA = pa.DataFrameSchema(
    {
        # BPS four-digit kabupaten code identifying the polygon.
        "kabupaten_code": pa.Column(int, nullable=False, coerce=True),
        # Calendar date of the daily ERA5-Land aggregate.
        "date": pa.Column(pa.DateTime, nullable=False, coerce=True),
        # Daily polygon-mean 2m air temperature in Celsius.
        "tmean_c": pa.Column(float, nullable=False, coerce=True),
        # Daily maximum 2m air temperature in Celsius.
        "tmax_c": pa.Column(float, nullable=False, coerce=True),
        # Daily minimum 2m air temperature in Celsius.
        "tmin_c": pa.Column(float, nullable=False, coerce=True),
        # Daily polygon-mean 2m dewpoint temperature in Celsius.
        "dewp_c": pa.Column(float, nullable=False, coerce=True),
        # Daily total precipitation in millimeters.
        "precip_mm": pa.Column(float, checks=pa.Check.ge(0), nullable=False, coerce=True),
        # Relative humidity percentage derived from mean temperature and dewpoint.
        "rh_pct": pa.Column(float, checks=pa.Check.between(0, 100), nullable=False, coerce=True),
        # Steadman/NWS heat index in Celsius derived from temperature and humidity.
        "heat_idx_c": pa.Column(float, nullable=False, coerce=True),
    },
    strict=True,
    ordered=True,
)

# Generated by code/data/07_compute_heat_features.py -> data/generated/daily_temperature_kab.parquet
DAILY_TEMPERATURE_HEAT_SCHEMA = pa.DataFrameSchema(
    {
        # Base daily weather columns from DAILY_TEMPERATURE_SCHEMA.
        **DAILY_TEMPERATURE_SCHEMA.columns,
        # Indicator that daily maximum temperature is at least 28 C.
        "hot28": _binary_column(),
        # Indicator that daily maximum temperature is at least 30 C.
        "hot30": _binary_column(),
        # Indicator that daily maximum temperature is at least 32 C.
        "hot32": _binary_column(),
        # Count of hot28 days in the current and previous 6 days.
        "hot28_7d": pa.Column(float, checks=pa.Check.between(0, 7), nullable=False, coerce=True),
        # Count of hot28 days in the current and previous 29 days.
        "hot28_30d": pa.Column(float, checks=pa.Check.between(0, 30), nullable=False, coerce=True),
        # Count of hot30 days in the current and previous 6 days.
        "hot30_7d": pa.Column(float, checks=pa.Check.between(0, 7), nullable=False, coerce=True),
        # Count of hot30 days in the current and previous 29 days.
        "hot30_30d": pa.Column(float, checks=pa.Check.between(0, 30), nullable=False, coerce=True),
        # Count of hot32 days in the current and previous 6 days.
        "hot32_7d": pa.Column(float, checks=pa.Check.between(0, 7), nullable=False, coerce=True),
        # Count of hot32 days in the current and previous 29 days.
        "hot32_30d": pa.Column(float, checks=pa.Check.between(0, 30), nullable=False, coerce=True),
        # Cooling degree days using 22 C as the base temperature.
        "cdd": pa.Column(float, checks=pa.Check.ge(0), nullable=False, coerce=True),
        # Seven-day rolling sum of cooling degree days.
        "cdd_7d": pa.Column(float, checks=pa.Check.ge(0), nullable=False, coerce=True),
        # Rolling 30-day kabupaten-specific 90th percentile of mean temperature.
        "tmean_p90_30d": pa.Column(float, nullable=True, coerce=True),
        # Indicator that mean temperature is at least the kabupaten p90 over the pulled window.
        "is_extreme": _binary_column(),
    },
    strict=True,
    ordered=True,
)

