# Generated by code/data/10_financial_shocks.py -> data/generated/financial_shocks.parquet
FINANCIAL_SHOCKS_SCHEMA = pa.DataFrameSchema(
    {
        # Stable IFLS person identifier, used as the person-level merge key.
        "pidlink": _id_column(),
        # IFLS survey wave for the financial-shock record.
        "wave": _wave_column(),
        # Respondent had at least one job termination in the past 5 years.
        "recent_job_loss_5y": _binary_column(),
        # Last job termination reason was fired, laid off, or plant closure.
        "involuntary_loss_5y": _binary_column(),
        # Days between interview date and the last reported job termination date.
        "days_since_last_loss": pa.Column(float, nullable=True, coerce=True),
        # Last job termination occurred within 365 days before interview.
        "job_loss_within_yr": _binary_column(),
        # Household owns a vehicle.
        "vehicle_owner": _binary_column(),
        # Household is in an urban area according to the screening file.
        "urban": _binary_column(),
        # Household received a cash-transfer benefit or held a BLT card.
        "cash_transfer_recipient": _binary_column(),
        # Household held a BLT cash-transfer card.
        "blt_card": _binary_column(),
        # Household held a health insurance or health assistance card.
        "health_card": _binary_column(),
        # Household province is in the Sumatra/Kalimantan palm-oil region.
        "palm_region": _binary_column(),
        # World Bank monthly palm-oil price for the interview month, USD/MT.
        "palm_price_usd_mt": pa.Column(float, checks=pa.Check.ge(0), nullable=True, coerce=True),
        # Z-score of the interview-month palm-oil price over the script's price history.
        "palm_price_z": pa.Column(float, nullable=True, coerce=True),
        # Low palm-price exposure: palm region times the negative part of palm_price_z.
        "palm_shock": pa.Column(float, checks=pa.Check.ge(0), nullable=False, coerce=True),
    },
    strict=True,
    ordered=True,
)

